package mcp

import (
	"context"
	"fmt"
	"strings"

	"github.com/modelcontextprotocol/go-sdk/mcp"

	mwanachamaagency "github.com/aosanya/mwanachama-backend-agency"
	"github.com/aosanya/mwanachama-backend-agency/models"
)

// registerIssueTools registers the Issue tool — system-detected
// diagnostics (e.g. a dangling reference, an Objective with no
// Accountable). List-only: an Issue is always regenerated by the scan
// agency_list_issues itself runs, never created/updated/deleted directly.
func registerIssueTools(server *mcp.Server, resolve ManagerResolver) {
	mcp.AddTool(server, &mcp.Tool{
		Name:        "agency_list_issues",
		Title:       "List Issues",
		Description: "Re-scan a Draft and list its current issues (info/warning/error) — e.g. a Work Item whose Objective no longer exists, an Objective with no Accountable role, or a Goal with no Objectives. This is exactly what agency_publish_agency validates against before publishing that Draft.",
	}, mcpListIssues(resolve))
}

type mcpListIssuesParams struct {
	InstanceID string `json:"instance_id" jsonschema:"which Agency this operates on, as resolved by the mounting host"`
	DraftID    string `json:"draft_id" jsonschema:"the Draft to scan"`
	Message    string `json:"message,omitempty" jsonschema:"filter: case-insensitive substring match on Message"`
	Severity   string `json:"severity,omitempty" jsonschema:"filter: exact match on Severity (info, warning, error)"`
	EntityType string `json:"entity_type,omitempty" jsonschema:"filter: exact match on EntityType (e.g. objective, goal)"`
}

func mcpListIssues(resolve ManagerResolver) func(context.Context, *mcp.CallToolRequest, mcpListIssuesParams) (*mcp.CallToolResult, ListResult[models.Issue], error) {
	return func(ctx context.Context, _ *mcp.CallToolRequest, p mcpListIssuesParams) (*mcp.CallToolResult, ListResult[models.Issue], error) {
		m, err := resolve(ctx, p.InstanceID)
		if err != nil {
			return nil, ListResult[models.Issue]{}, err
		}
		out, err := m.ListIssues(ctx, p.DraftID, mwanachamaagency.IssueFilter{
			Message:    p.Message,
			Severity:   p.Severity,
			EntityType: p.EntityType,
		})
		return summaryWithContext(fmt.Sprintf("Found %d issue(s)", len(out)), issuesContextText(out)), ListResult[models.Issue]{Items: out}, err
	}
}

// issuesContextText mirrors objectivesContextText — one line per Issue for
// an LLM reading a dashboard-opened list outside its own tool loop.
func issuesContextText(issues []models.Issue) string {
	if len(issues) == 0 {
		return "There are no issues."
	}
	lines := make([]string, 0, len(issues))
	for _, i := range issues {
		line := fmt.Sprintf("- [%s] %s", i.Severity, i.Message)
		if i.EntityType != "" {
			line += fmt.Sprintf(" (%s id: %s)", i.EntityType, i.EntityID)
		}
		lines = append(lines, line)
	}
	return "Current issues:\n" + strings.Join(lines, "\n")
}
